import { Citation } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof Citation>, 'index' | 'source'> = {
    index: 1,
    source: {
      title: 'Understanding Success Criterion 1.4.3: Contrast (Minimum)',
      href: 'https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html',
      snippet: 'Text and images of text have a contrast ratio of at least 4.5:1.',
    },
  };
  return <Citation {...args} />;
}

import { Citation } from '@refy-design/web';
export function Example() {
  return (
    <p style={{ maxWidth: 520 }}>
      Body text needs a contrast ratio of at least 4.5 to 1
      <Citation
        index={1}
        source={{
          title: 'Understanding Success Criterion 1.4.3',
          href: 'https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html',
          snippet: 'Text and images of text have a contrast ratio of at least 4.5:1.',
        }}
      />
      , and large text can go down to 3 to 1
      <Citation
        index={2}
        source={{
          title: 'Large text definition',
          href: 'https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html#dfn-large-scale',
          snippet: 'At least 18 point, or 14 point bold.',
        }}
      />
      .
    </p>
  );
}
